package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.mockStatic;

import org.lwjgl.util.lmdb.LMDB;
import org.mockito.MockedStatic;

/** Calling-thread real native work; parallel callers require a separate uninstrumented engagement test. */
final class LmdbAdjacencyNativeReadWork implements AutoCloseable {
	private final Thread owner = Thread.currentThread();
	private final MockedStatic<LMDB> mock;
	private int depth;
	private long gets;
	private long moves;

	LmdbAdjacencyNativeReadWork() {
		mock = mockStatic(LMDB.class, invocation -> {
			boolean outermost = depth++ == 0;
			try {
				if (outermost) {
					assertThat(Thread.currentThread()).isSameAs(owner);
					switch (invocation.getMethod().getName()) {
					case "mdb_get" -> gets++;
					case "mdb_cursor_get" -> moves++;
					default -> {
					}
					}
				}
				return invocation.callRealMethod();
			} finally {
				depth--;
			}
		});
	}

	Counts counts() {
		return new Counts(gets, moves);
	}

	record Counts(long gets, long moves) {
		void assertBoundedBy(Counts smaller) {
			assertThat(smaller.gets + smaller.moves).as("real native reads observed in the smaller case").isPositive();
			assertThat(gets + moves).as("real native reads observed in the larger case").isPositive();
			assertThat(gets).as("unselected population must not increase point-read work")
					.isLessThanOrEqualTo(smaller.gets + 8);
			assertThat(moves).as("unselected population must not increase cursor-read work")
					.isLessThanOrEqualTo(smaller.moves + 8);
		}
	}

	@Override
	public void close() {
		mock.close();
	}
}
